\label{rmk:spectral_decomp_conti} (Yaglom 1987) \cite{yaglom1987correlation},
Let $X(t)$ be a random process with stationary increments with order $d$, and $Y(t)$ be a stationary random process such that $Y=X^{(d)}$, which is a d-th derivative (or generalized derivative) of $X$, where $t,h \in \mathbb{R}$. Since $Y(t)$ is stationary,

\begin{align}
&Y(t) =  \int_{-\infty}^{\infty}e^{i \omega t}dZ_y(\omega), \quad E \bigl(Y(t+h) \cdot Y(t) \bigl) = C_y(h) = \int_{-\infty}^{\infty}e^{i \omega h}dF_y(\omega), \label{eq:corr_y}
\end{align}

where $F_y(\omega)$ is a bounded non-decreasing function and $E(|dZ_y(\omega)|^2) = dF_y(\omega)$ for $Z_y(\omega)$, a random function with uncorrelated increments. Then, we can achieve the following spectral representations:
\begin{align}
X(t) &=  \int_{-\infty}^{\infty} \bigl( e^{it\omega} -1 - it\omega - \cdots - \frac{(i t \omega)^{d-1}}{(d-1)!} \bigl) dZ(\omega) + X_0 + X_1 t + \cdots + X_d t^d \label{eq:spectra_I(d)}\\
\Delta_{\iota}^d X(t) &= \int_{-\infty}^{\infty} e^{i\omega t} (1-e^{-i \iota\omega})^d dZ(\omega) + (d!) X_d \iota^d \label{eq:spectral_differenced} \\
D(h; \iota_1,\iota_2) &= \int_{-\infty}^{\infty} e^{i\omega h} (1-e^{-i \omega \iota_1})^d (1-e^{i \omega \iota_2})^d dF(\omega) + (d!)^2 A_d^2 \iota_1^d \iota_2^d \label{eq:spectral_structur_fn}


\end{align}
Where  $\int_{-\infty}^{\infty} = \lim_{T \rightarrow \infty, \epsilon \rightarrow 0} \{ \int_{-T}^{-\epsilon} + \int_{\epsilon}^{T}\}$, \quad $Z(\omega_2) - Z(\omega_1) = \int_{-\omega_1}^{\omega_2} \frac{dZ_y(\omega)}{(i \omega)^d}$, \quad and \quad $F(\omega_2) - F(\omega_1) = \int_{-\omega_1}^{\omega_2} \frac{dF_y(\omega)}{\omega^{2d}}$.  A random variable $X_0 = X(0)$ and $X_1, X_2, \cdots, X_{d-1}$ are some random variables. A random variable $X_d$ is  introduced in order to deal with the jump discontinuity at $\omega=0$. These random variables $X_0, X_1, \cdots, X_d$ can, in particular, be constants. In the structure function, $\langle|X_d| \rangle = A_d^2 \ge 0$.

\label{rmk:spectral_decomp_conti2} (Yaglom 1987) \cite{yaglom1987correlation}
If the correlation function of $C_y(h)$ in \eqref{eq:corr_y} decays rapidly with respect to $h$, that is,
\begin{align}
    &\int_{-\infty}^{\infty} |C_y(h)|^2 dh < \infty \label{eq:corr_y_decay}
\end{align}
then, the random variable $X_d$ and $A_d$ in \eqref{eq:spectra_I(d)}, \eqref{eq:spectral_differenced}, and \eqref{eq:spectral_structur_fn} are zero, and the spectral density function of the process $X(t)$ exists; thus, the spectral distribution function $dF(\omega)$ in \eqref{eq:spectral_structur_fn} can be expressed as $f(\omega)d\omega$ where $f(\omega) = F'(\omega)$. In the later part of this research, we assume the condition in \eqref{eq:corr_y_decay} is satisfied. We also assume that the random variables $X_0, X_1, \cdots, X_{d-1}$ are zero for simplicity.

\label{def:irf_temporal}
A random process $X(t)$ on the real line is an intrinsic random function with its order $d$, denoted IRF(d), if the process $X(\lambda)$ is shift invariant for any $t \in \mathbb{R}$ and any $\lambda \in \Lambda_d$. That is, for any allowable measure $\lambda \in \Lambda_d$ and any $\tau_h \in \mathrm{G}$ where $\mathrm{G}$ is a group of shift operators and $h \in \mathbb{R}$, it satisfies that
\begin{align*}
&E\bigl(X(\lambda) \bigl) = E\bigl(X(\tau_h \lambda) \bigl)\\
&Cov\bigl(X(\lambda_1), X(\lambda_2) \bigl) = Cov\bigl(X(\tau_h \lambda_1), X(\tau_h \lambda_2) \bigl) \quad \text{where} \quad \text{any }\lambda_1, \lambda_2 \in \Lambda_d
\end{align*}

Suppose that the random process $Y(t)$ is stationary for $t \in \mathbb{R}$, as in Definition~\ref{def:Stationarity}, and let $\lambda \in \Lambda_d$ be any allowable measure with compact support, where $d \in \mathbb{Z}_+$.

\begin{align*}
    E\bigl( Y(\lambda) \bigl) &= E\bigl( \int Y(t) \lambda(dt) \bigl)\\
    &= \int E\bigl( Y(t) \bigl) \lambda(dt)
\end{align*}
since the order of integration and expectation can be interchanged by the Fubini's theorem in that $\lambda$ has compact support (finite measure) and $Y(t)$ is continuous in quadratic mean (implying integrability in the $L^2$ sense). Then, by stationarity of $Y(t)$ in terms of t, for any $h\in \mathbb{R}$, we can also state that
\begin{align*}
   \int E\bigl( Y(t) \bigl) \lambda(dt) &= \int E\bigl( Y(t+h) \bigl) \lambda(dt)\\
    &= E\bigl( \int Y(t+h) \lambda(dt) \bigl) = E\bigl( Y(\tau_h \lambda) \bigl)\\
\end{align*}
since $\tau_h \lambda$ is still a finite measure.

Similarly, for any $\lambda_1, \lambda_2 \in \Lambda_d$ with compact support, $d \in \mathbb{Z}_+$, and $t,s \in \mathbb{R}$,
\begin{align*}
    Cov\bigl( Y(\lambda_1), Y(\lambda_2) \bigl) &= Cov\bigl( \int Y(t) \lambda_1(dt), \int Y(s) \lambda_{2}(ds) \bigl)\\
    &= \int \int Cov\bigl( Y(t), Y(s) \bigl) \lambda_1(dt) \lambda_2(ds) \quad \text{(by Fubini's thoerem with the same reasons)}
\end{align*}
By stationarity of $Y(t)$ in terms of any $t \in \mathbb{R}$, for any $h\in \mathbb{R}$,
\begin{align*}
    Cov\bigl( Y(\lambda_1), Y(\lambda_2) \bigl) &= Cov\bigl( \int Y(t) \lambda_1(dt), \int Y(s) \lambda_{2}(ds) \bigl)\\
    &= \int \int Cov\bigl( Y(t+h), Y(s+h) \bigl) \lambda_1(dt) \lambda_2(ds)\\
    &= Cov\bigl(\int Y(t+h) \lambda_1(dt), \int Y(s+h) \lambda_2(ds) \bigl)\\
    &= Cov\bigl( Y(\tau_h \lambda_1), Y(\tau_h \lambda_2) \bigl)
\end{align*}
Therefore, if $Y(t)$ is stationary for any $t \in \mathbb{R}$, then $Y(\lambda)$ is stationary for $\lambda$, an allowable measure with any order.

\label{rmk:structure_fn_and_ICF}
    Let $X(\cdot)$ be an intrinsic random function of order $d$ on $\mathbb{R}$, denoted as IRF$(d)$. Let $K(\cdot)$ be its intrinsic covariance function of $X(\cdot)$ in Definition~\ref{def:icf}. Then, the structure function $E\biggl( \Delta_{\iota_1}^{d}X(t) \cdot \Delta_{\iota_2}^{d}X(s) \biggl)$ in Definition~\ref{def:random_process_stationary_increment} can be expressed in terms of the intrinsic covariance function as
    \begin{align*}
        E\bigl( \Delta_{\iota_1}^{d}X(t) \cdot \Delta_{\iota_2}^{d}X(s) \bigl) &= \sum_{k_1=0}^{d} (-1)^{k_1} \binom{d}{k_1} \sum_{k_2=0}^{d} (-1)^{k_2} \binom{d}{k_2} K\bigl( (t - k_1 \iota_1) - (s-k_2 \iota_2) \bigl)
    \end{align*}
